def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_moves = [h[0] for h in history]
    opp_moves = [h[1] for h in history]
    opp_defects = sum(1 for o in opp_moves if o == 'D')
    my_defects = sum(1 for m in my_moves if m == 'D')
    last_my, last_opp = history[-1]

    # Check for exploit mode: we defected while opponent cooperated, and they did not retaliate next round.
    first_exploit = -1
    for i in range(n):
        if my_moves[i] == 'D' and opp_moves[i] == 'C':
            first_exploit = i
            break

    if first_exploit != -1 and first_exploit + 1 < n:
        if opp_moves[first_exploit + 1] == 'C':
            # Opponent did not retaliate to our first defection.
            # If they haven't defected since, we are in exploit mode.
            if not any(opp_moves[j] == 'D' for j in range(first_exploit + 1, n)):
                return 'D'

    # Normal adaptive TFT
    if last_opp == 'D':
        if last_my == 'D':
            # DD: try to break out if opponent is not mostly defective.
            if opp_defects * 2 > n:
                return 'D'
            else:
                return 'C'
        else:
            # We cooperated, opponent defected.
            # If we defected in the previous round, it's retaliation; apologize.
            if n >= 2 and my_moves[-2] == 'D':
                return 'C'
            else:
                return 'D'
    else:
        # last_opp == 'C'
        if last_my == 'D':
            # We defected, opponent cooperated. Apologize.
            return 'C'
        else:
            # Mutual cooperation. Probe if we haven't probed and opponent has been very cooperative.
            if my_defects == 0 and opp_defects == 0 and n >= 10:
                return 'D'
            return 'C'
